INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','easy','flashcard','What is the difference between a TIA and ischaemic stroke?','["TIA: focal neurological deficit that resolves completely, typically within 1 hour (by definition <24 hrs), without evidence of infarction on MRI DWI. Ischaemic stroke: focal neurological deficit persisting >24 hrs (or <24 hrs with MRI-confirmed infarction). The 2009 tissue-based definition: any focal brain infarction (DWI lesion) = stroke, even if symptoms resolve quickly. TIA risk of stroke: 10-15% within 90 days, highest in first 48 hrs (ABCD2 score stratifies risk)."]','A','TIA = temporary. Stroke = permanent infarct. DWI decides.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','easy','flashcard','What is the ischaemic penumbra and why is it important clinically?','["The penumbra is the zone of ischaemic but potentially salvageable tissue surrounding the infarct core. It has reduced blood flow (15-40 mL/100g/min — between the threshold for electrical failure [~20 mL/100g/min] and the threshold for ionic failure and cell death [~10 mL/100g/min]). Penumbra maintains membrane potential but not function. It is the target of acute stroke treatment (thrombolysis, thrombectomy) to salvage tissue and reduce disability. Time = brain (1.9 million neurons lost per minute without treatment)."]','A','Penumbra = alive but sick tissue. Treat fast to save it. Time = brain.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','medium','flashcard','Describe the histological timeline of ischaemic stroke.','["0-12 hrs: brain appears grossly normal (no gross change), minimal histological change. 12-24 hrs: red neurons (eosinophilic cytoplasm, pyknotic nucleus). 24-72 hrs: neutrophil infiltration (acute inflammation), early liquefactive necrosis. 3-5 days: macrophage (foam cell) infiltration dominates, begins phagocytosing necrotic tissue. 1-2 weeks: reactive astrocytosis at periphery, angiogenesis. Months: glial scar (astrocytosis) replaces necrotic cavity; a cystic cavity (encephalomalacia) may form."]','A','Red neurons early, neutrophils then macrophages then gliosis. RENS: Red, Expanding Neutrophils, then Scavengers, then Scar.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','medium','flashcard','What are the four main mechanisms of ischaemic stroke?','["1) Large vessel atherosclerosis: in situ thrombosis on atherosclerotic plaque in large arteries (ICA, vertebral, basilar). 2) Cardioembolism: thrombus from AF, LV thrombus post-MI, valvular disease → embolism. 3) Small vessel disease: lipohyalinosis of perforating arteries → lacunar infarcts (hypertension). 4) Cryptogenic stroke (~30%): cause unknown despite investigation. Mnemonic: TOAST classification (Trial of ORG 10172 in Acute Stroke Treatment). Rare causes: dissection, vasculitis, hypercoagulable states."]','A','LAC-S: Large artery, AF/Cardioembolic, Cryptogenic, Small vessel. TOAST classification.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','medium','flashcard','What brain regions are MOST selectively vulnerable to global ischaemia?','["Most vulnerable (selective vulnerability): (1) Hippocampal CA1 neurons (Sommer sector). (2) Purkinje cells of the cerebellum. (3) Pyramidal neurons of neocortical layers III, V, VI. (4) Striatal neurons (caudate, putamen). These areas have: high metabolic rates, high NMDA receptor density (excitotoxicity susceptibility), and poor antioxidant capacity. The CA2 region and brainstem nuclei are relatively resistant."]','A','CA1 most vulnerable in hippo; Purkinje in cerebellum; layers III, V, VI in cortex. EXCITOTOXIC hotspots.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','medium','flashcard','What is diffusion-weighted imaging (DWI) in stroke and what does it detect?','["DWI measures the BROWNIAN MOTION of water molecules. In acute ischaemic stroke: cytotoxic oedema (Na+/K+ ATPase failure → intracellular Na+ and water → cell swelling) restricts extracellular water diffusion → DWI BRIGHT (high signal) and ADC (apparent diffusion coefficient) DARK/LOW. DWI detects ischaemia within MINUTES of onset (much earlier than CT or conventional MRI). DWI-FLAIR mismatch: DWI+ but FLAIR- suggests onset <4.5 hours (wake-up stroke imaging)."]','A','DWI bright + ADC dark = cytotoxic oedema = acute ischaemia. Appears within minutes!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','medium','flashcard','What is the ABCD2 score used for in TIA management?','["ABCD2 score stratifies SHORT-TERM STROKE RISK after TIA: A=Age (>=60 yrs = 1pt), B=BP at presentation (>=140/90 = 1pt), C=Clinical features (unilateral weakness = 2pts; speech disturbance = 1pt), D=Duration (>=60 min = 2pts; 10-59 min = 1pt), D2=Diabetes (1pt). Maximum 7 points. High risk (>=4): admit for urgent investigation and secondary prevention. Note: even low-ABCD2 TIAs may need admission based on imaging."]','A','ABCD2: Age, BP, Clinical, Duration, Diabetes. High score = high risk. Admit and investigate urgently.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','hard','flashcard','Explain the mechanism of ischaemic cell death (excitotoxicity).','["1) Ischaemia: ATP failure → Na+/K+ ATPase stops → intracellular Na+ rises → membrane depolarises. 2) Voltage-gated Ca2+ channels open → Ca2+ influx. 3) Glutamate accumulates in the extracellular space (impaired reuptake) → NMDA and AMPA receptor overactivation → more Ca2+ and Na+ influx (excitotoxicity). 4) Ca2+ activates: caspases (apoptosis), calpains (cytoskeletal damage), phospholipases (membrane damage), nitric oxide synthase (free radical production), mitochondrial permeability transition (necrosis). Result: necrosis (core) and apoptosis (penumbra)."]','A','Ca2+ overload is the executor. Glutamate pulls the trigger via NMDA receptors. Ca2+ kills the neuron.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','hard','flashcard','What is haemorrhagic transformation of ischaemic stroke, when does it occur, and what risk factors increase it?','["Haemorrhagic transformation (HT): bleeding into an ischaemic infarct, ranging from petechiae (HI1) to confluent haematoma (PH2) by ECASS classification. Occurs as BBB breakdown allows reperfusion bleeding. Timing: typically days 1-5. Risk factors for HT: large infarct size, cardioembolic aetiology, delayed reperfusion, anticoagulation, thrombolysis (tPA), prior antiplatelet therapy, hyperglycaemia, malignant MCA infarction. Symptomatic HT (SICH): neurological deterioration due to haematoma — major complication of tPA."]','A','Haemorrhagic transformation: infarcted brain bleeds when reperfused. Large cardioembolic stroke + tPA = highest risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Ischemic Stroke','easy','flashcard','What are the key brain arterial territories and what deficits result from their occlusion?','["ACA territory (medial frontal/parietal lobe): contralateral leg weakness/sensory loss, urinary incontinence, abulia. MCA territory (lateral cortex): contralateral face/arm greater than leg weakness/sensory, aphasia (dominant) or neglect (non-dominant), gaze preference toward lesion, homonymous hemianopia. PCA territory (occipital lobe, thalamus): homonymous hemianopia, alexia without agraphia (dominant), thalamic syndrome. Brainstem: diplopia, dysarthria, ataxia, crossed deficits."]','A','ACA = leg. MCA = face+arm+language. PCA = vision. Brainstem = crossed deficits.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','easy','flashcard','What is the classic presentation of subarachnoid haemorrhage (SAH) from a ruptured berry aneurysm?','["Sudden onset THUNDERCLAP HEADACHE (worst headache of one''''s life, maximal in seconds), nausea/vomiting, meningism (neck stiffness, photophobia, Kernig/Brudzinski signs), brief loss of consciousness (in ~50%), and sometimes focal neurological deficits. Sentinel headache in ~30%: warning bleed hours-days before major SAH. CT sensitivity for SAH: ~98% within 12 hours (blood in subarachnoid/basal cisterns). If CT negative and SAH suspected: LP at 12 hrs for xanthochromia."]','A','Thunderclap headache + meningism + CT blood in cisterns = SAH until proven otherwise.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','easy','flashcard','What are the pathological characteristics of a berry (saccular) aneurysm?','["Saccular dilatation at arterial bifurcations in the circle of Willis. Pathology: congenital deficiency of the tunica media (smooth muscle) and internal elastic lamina at the bifurcation point (where haemodynamic stress is greatest). The wall is composed of fibrous tissue and intima only. The dome of the aneurysm is thin and prone to rupture. Size: most rupture at >7 mm (ISAT study), but small aneurysms can rupture. Hypertension accelerates growth."]','A','Berry aneurysm: no media at bifurcation. Thin dome. Blood pressure stretches it open.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','medium','flashcard','What are the complications of SAH and their timing?','["Early (<72 hrs): rebleed (highest risk in first 24 hrs, 50% mortality). Days 1-3: acute hydrocephalus (blood blocking CSF absorption). Days 4-14: vasospasm and delayed cerebral ischaemia (DCI) — most common cause of death and disability after initial SAH. Days 1-14: hyponatraemia (SIADH or cerebral salt wasting), cardiac complications (T-wave inversion, Takotsubo cardiomyopathy from catecholamine surge). Late: chronic hydrocephalus (months), epilepsy."]','A','RVSHE: Rebleed (early), Vasospasm (days 4-14), Hydrocephalus, Seizures, HypothErmiaNatraemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','medium','flashcard','Differentiate epidural haematoma (EDH) from subdural haematoma (SDH) on CT scan.','["EDH: BICONVEX (lens-shaped) hyperdensity (acute blood), does NOT cross suture lines (periosteum fused at sutures), most common temporal location (middle meningeal artery). Classic: lucid interval then rapid deterioration. EDH = arterial (middle meningeal artery). SDH: CRESCENT-shaped hyperdensity (acute), can cross suture lines (but not midline/tentorium), most common over the convexities. SDH = venous (bridging veins). Chronic SDH: hypodense (isodense at 2-3 weeks)."]','A','EDH = biconvex lens, doesn''''t cross sutures, arterial. SDH = crescent, crosses sutures, venous.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','medium','flashcard','What is hypertensive intracerebral haemorrhage and what are its typical locations?','["Hypertensive ICH: rupture of small penetrating arteries (Charcot-Bouchard microaneurysms) weakened by chronic hypertension (lipohyalinosis, fibrinoid necrosis). Typical locations (in decreasing frequency): 1) Putamen/basal ganglia (50%). 2) Thalamus (15%). 3) Pons (10-15%). 4) Cerebellum (10%). 5) Subcortical/lobar (10-15%). Lobar ICH in elderly without hypertension: think cerebral amyloid angiopathy (CAA). Lobar ICH in young: AVM, tumour, drug use (cocaine/amphetamine)."]','A','PUT the Thalamus Pons Cerebellum! Putamen #1 in hypertensive ICH. Lobar = think CAA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','medium','flashcard','What is cerebral amyloid angiopathy (CAA) and how does it present?','["CAA: deposition of amyloid-beta (Abeta40 predominantly) in the walls of cortical and leptomeningeal small and medium arteries/arterioles. Weakens vessel walls → LOBAR haemorrhage (cortical/subcortical, not deep). Epidemiology: >60 years, associated with Alzheimer disease. MRI (GRE/SWI): multiple cortical microbleeds, cortical superficial siderosis (haemosiderin lining sulci). Genetics: APOE4 allele increases risk of CAA. No specific treatment; anticoagulation is hazardous."]','A','CAA = amyloid in vessel wall = LOBAR bleeds in elderly. SWI shows microbleeds. Avoid anticoagulants.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','medium','flashcard','What is vasospasm after SAH and how is it managed?','["Vasospasm: symptomatic narrowing of large cerebral arteries (circle of Willis and MCA/ACA/PCA) due to blood breakdown products (oxyhaemoglobin, endothelin, bilirubin oxidation products). Onset: days 4-14 post-SAH (peak day 7-10). Clinical: deteriorating consciousness/new focal deficits. Monitoring: transcranial Doppler (TCD) — MCA velocity >200 cm/s indicates severe vasospasm. Treatment: oral/IV NIMODIPINE (reduces calcium entry in vascular smooth muscle, reduces DCI incidence and improves outcomes) + maintain adequate hydration + consider intra-arterial vasodilators or balloon angioplasty."]','A','Vasospasm: oxyhaemoglobin = arterial spasm. Days 4-14. Nimodipine prevents DCI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','hard','flashcard','What is the pathophysiology of delayed cerebral ischaemia (DCI) after SAH?','["DCI is caused by multiple mechanisms: 1) Large vessel vasospasm (classical mechanism). 2) Cortical spreading depolarisations (CSD): waves of neuronal/glial depolarisation propagating through the cortex, greatly increasing metabolic demand — subarachnoid blood triggers CSD. 3) Microthrombosis: platelet aggregation and fibrin deposition in small arteries/capillaries. 4) Neuroinflammation: activation of microglia, astrocytes, and infiltration of neutrophils/macrophages. 5) BBB disruption leading to vasogenic oedema. Vasospasm alone does not explain all DCI."]','A','DCI: not just vasospasm. CSD + microthrombi + inflammation all contribute. Complex pathophysiology.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','hard','flashcard','What genetic conditions are associated with cerebral berry aneurysm formation?','["Conditions associated with intracranial aneurysms: 1) ADPKD (autosomal dominant polycystic kidney disease, PKD1/PKD2 genes): ~10-15% have intracranial aneurysms. 2) NF1 (neurofibromatosis type 1). 3) Marfan syndrome (FBN1). 4) Ehlers-Danlos syndrome type IV (COL3A1 — collagen deficiency). 5) Coarctation of the aorta (from increased haemodynamic stress). Family history: first-degree relatives of SAH patients have 3-7x increased risk. Screening offered in selected high-risk families."]','A','ADPKD + coarctation of aorta = screen for aneurysm. Berry aneurysm = congenital medial defect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Cerebrovascular Disease - Haemorrhagic','easy','flashcard','What is the Monro-Kellie doctrine and how does it explain ICH pathophysiology?','["Monro-Kellie: the skull is a rigid container with fixed total volume (brain ~80%, blood ~10%, CSF ~10%). Any expanding haematoma initially compresses CSF and venous blood to compensate (compensation phase = flat ICP curve). Once compensatory mechanisms are exhausted, ICP rises sharply (decompensation) leading to herniation. This explains why ICH can rapidly progress from stable to herniation: the brain has been compensating until suddenly it cannot."]','A','Rigid skull: ICH expands → compensates (CSF out) → then ICP rises exponentially → herniation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','easy','flashcard','List the common organisms causing bacterial meningitis by age group.','["Neonates (0-1 month): Group B Streptococcus, E. coli, Listeria monocytogenes. Infants (1-23 months): S. pneumoniae, N. meningitidis, H. influenzae (declining due to vaccination). Children/Young adults (2-50 yrs): N. meningitidis (meningococcal), S. pneumoniae. Adults >50 yrs: S. pneumoniae, Listeria monocytogenes, gram-negative bacilli. Empirical treatment: neonates = ampicillin + cefotaxime + gentamicin; adults = ceftriaxone + vancomycin + dexamethasone (+ampicillin if Listeria risk)."]','A','Neonates GBS+E.coli+Listeria. Young adults = meningococcal. Adults >50 = pneumococcal+Listeria. Add ampicillin for Listeria!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','easy','flashcard','What are the pathological findings of acute bacterial meningitis?','["Gross: purulent exudate filling the subarachnoid space (basal cisterns, sulci over convexities). Microscopically: neutrophilic infiltrate in the pia/arachnoid, fibrin, and bacteria. Complications: cortical vein thrombosis, vasculitis causing infarcts, communicating hydrocephalus (arachnoid adhesions), subdural empyema, brain abscess, septicaemia, DIC, Waterhouse-Friderichsen syndrome (meningococcal — adrenal haemorrhage)."]','A','Pus in subarachnoid space = bacterial meningitis. Purulent = neutrophils + bacteria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','medium','flashcard','What CSF changes are expected in bacterial vs. viral vs. TB meningitis?','["Bacterial: turbid/cloudy, HIGH pressure, NEUTROPHILS (>1000/mm3), HIGH protein (>100 mg/dL), VERY LOW glucose (<40% serum). Viral (aseptic): clear, normal/mildly raised pressure, LYMPHOCYTES (10-500/mm3), NORMAL/mildly raised protein, NORMAL glucose. TB: clear/slightly turbid, HIGH pressure, LYMPHOCYTES (100-500/mm3), VERY HIGH protein (often >100), VERY LOW glucose, AFB smear low sensitivity."]','A','GPLC bacteria: neutrophils, low glucose. Viral: lymphocytes, normal glucose. TB: lymphocytes, very low glucose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','medium','flashcard','What is the triad of herpes simplex encephalitis and how is it treated?','["HSE (mostly HSV-1 in adults): presents with FEVER + TEMPORAL LOBE DYSFUNCTION (personality change, confusion, memory disturbance, olfactory/gustatory hallucinations, aphasia, complex partial seizures). EEG: periodic lateralised epileptiform discharges (PLEDs) from temporal lobes. MRI: T2/FLAIR hyperintensity in temporal lobes (asymmetric, unilateral early). CSF: HSV PCR (gold standard, >95% sensitivity/specificity). Treatment: IMMEDIATE IV ACYCLOVIR (10 mg/kg TDS for 14-21 days). Do NOT wait for PCR result."]','A','HSE = fever + temporal lobe signs + temporal MRI changes. Treat with acyclovir NOW.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','medium','flashcard','What is a brain abscess, what are the typical pathogens, and how does it appear on CT/MRI?','["Brain abscess: focal suppurative infection within the brain parenchyma. Stages: early cerebritis (no capsule) → late cerebritis → early capsule → late capsule (established abscess). Pathogens: Streptococcus (viridans group, S. milleri group), anaerobes (from dental/sinus source), Staphylococcus (trauma/post-surgical), gram-negatives (in immunocompromised). CT/MRI: RING-ENHANCING LESION (enhancing capsule around central necrotic/pus core) with surrounding vasogenic oedema and mass effect. Differential: GBM, metastasis, tumefactive MS."]','A','Brain abscess = ring-enhancing lesion + oedema. Differential: GBM, mets. Strep + anaerobes most common.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','medium','flashcard','What is tuberculous meningitis and what are its complications?','["TB meningitis: Mycobacterium tuberculosis spreads haematogenously from primary lung focus. Pathology: granulomatous basilar meningitis (gelatinous exudate at base of brain). Complications: (1) Cranial nerve palsies (CN II, III, VI from basilar inflammation). (2) Communicating hydrocephalus (arachnoid adhesions blocking CSF absorption). (3) Cerebral infarction (endarteritis of perforating arteries). (4) Tuberculomas (granulomata in parenchyma). Treatment: RIPE (rifampicin, isoniazid, pyrazinamide, ethambutol) for 9-12 months + adjunctive dexamethasone (reduces mortality/disability)."]','A','TB meningitis: basilar exudate = CN palsies + hydrocephalus + infarcts. RIPE + steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','medium','flashcard','What is Cryptococcus neoformans meningitis and how is it diagnosed?','["Cryptococcus neoformans: encapsulated yeast, acquired by inhalation of pigeon droppings. Causes meningitis predominantly in immunocompromised (HIV CD4 <100, transplant). Pathology: minimal inflammatory response (immunocompromised = no pus) but yeast invades perivascular spaces (Virchow-Robin spaces) causing soap-bubble lesions in basal ganglia on MRI. CSF: minimal pleocytosis, HIGH opening pressure, positive India ink (clear halo around yeast), cryptococcal antigen (CRAG, very sensitive). Treatment: amphotericin B + flucytosine (induction) then fluconazole (consolidation/maintenance)."]','A','Crypto: India ink shows capsule. CRAG test. Soap-bubble lesions. HIV. Ampho B + 5FC = treat.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','hard','flashcard','What is the pathogenesis of bacterial meningitis from the point of nasopharyngeal colonisation to meningeal invasion?','["1) Nasopharyngeal colonisation (N. meningitidis, S. pneumoniae). 2) Evasion of mucosal immunity (IgA proteases). 3) Invasion of bloodstream → bacteraemia. 4) Survival in blood (anti-phagocytic capsule, serum resistance). 5) Crossing the BBB: bacteria cross via transcytosis through endothelial cells (pneumococcus via platelet-activating factor receptor) or Trojan horse (inside leukocytes). 6) In CSF: poor complement/immunoglobulin → bacteria proliferate → bacterial lysis → LPS/LTA → TLR activation → cytokine storm (TNF, IL-1, IL-6) → neutrophil recruitment → BBB damage → oedema → raised ICP."]','A','Colonise → bacteraemia → cross BBB → TLR/LPS → cytokines → neutrophils → brain damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','hard','flashcard','What are the causes and CSF features of eosinophilic meningitis?','["Eosinophilic pleocytosis in CSF (>10% eosinophils): most commonly caused by CNS PARASITES. Causes: Angiostrongylus cantonensis (rat lungworm — most common cause worldwide, Hawaii, SE Asia; from eating raw snails/slugs), Gnathostoma spinigerum (raw fish), Baylisascaris procyonis (raccoon roundworm), Toxocara, cysticercosis (Taenia solium), schistosomiasis. Non-parasitic: fungal meningitis, drug hypersensitivity, TB. Diagnosis: serology, CSF PCR/culture, eosinophilia in blood."]','A','Eosinophils in CSF = PARASITES! Angiostrongylus = raw snails. Gnathostoma = raw fish. Baylisascaris = raccoon.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Infections','easy','flashcard','What empirical antibiotic regimen is used for bacterial meningitis in adults, and why is dexamethasone added?','["Adults: CEFTRIAXONE (2g IV BD) + VANCOMYCIN (for cephalosporin-resistant S. pneumoniae) + DEXAMETHASONE (0.15 mg/kg QDS for 4 days, given 15-20 min before or with first antibiotic dose). Add AMPICILLIN if Listeria risk (age >55, immunocompromised, pregnant). Dexamethasone: reduces meningeal inflammation, decreases TNF/IL-1 cytokine cascade, reduces incidence of hearing loss (CN VIII), improves outcomes in pneumococcal meningitis. Give BEFORE antibiotics if possible (reduces cytokine release from bacterial lysis)."]','A','Ceftriaxone + vancomycin + dexamethasone. Dexamethasone = anti-inflammation BEFORE antibiotics. Add ampicillin for Listeria risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','easy','flashcard','What are the four major subtypes of MS and their clinical course?','["1) Relapsing-remitting MS (RRMS, ~85%): discrete relapses with complete/partial recovery between. 2) Secondary progressive MS (SPMS): after years of RRMS, gradual accumulation of disability without clear relapses. 3) Primary progressive MS (PPMS, ~15%): gradual neurological deterioration from onset (no relapses), older males, spinal cord dominant. 4) Progressive-relapsing MS (PRMS): rare, progressive from onset with occasional relapses. RRMS is the most common initial presentation; ~50% convert to SPMS by 10-15 years."]','A','RRMS (85%) converts to SPMS. PPMS starts progressive. RRMS = young women. PPMS = older men.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','easy','flashcard','What are oligoclonal bands (OCBs) and what do they indicate in MS?','["OCBs: distinct bands of IgG seen on isoelectric focusing of CSF electrophoresis that are PRESENT IN CSF but ABSENT IN SERUM (intrathecal IgG synthesis). Positive in >90% of MS patients. Significance: indicate CNS-restricted immune activation (inflammation within the CNS). Not specific for MS: also positive in CNS infections (syphilis, Lyme, TB), neurosarcoidosis, paraneoplastic syndromes. CSF OCBs can substitute for DIT in the 2017 McDonald MS diagnostic criteria."]','A','OCBs in CSF not serum = intrathecal IgG = CNS inflammation. MS, but also infections. Not specific.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','medium','flashcard','What are the 2017 McDonald criteria for MS diagnosis?','["Multiple sclerosis requires DISSEMINATION IN SPACE (DIS) AND DISSEMINATION IN TIME (DIT). DIS: lesions in >=2 of 4 locations: periventricular, juxtacortical/cortical, infratentorial, spinal cord. DIT: (1) New T2 or enhancing lesion on follow-up MRI, OR (2) Simultaneous asymptomatic Gd-enhancing and non-enhancing lesions. CSF OCBs can substitute for DIT. DIS and DIT can be met on first MRI if criteria met. Clinical diagnosis also requires exclusion of other diagnoses."]','A','DIS: lesions in 2+ regions. DIT: new lesion over time or Gd+/non-Gd+ lesions together. OCBs substitute for DIT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','medium','flashcard','What are the key features that distinguish NMOSD from MS?','["NMOSD (Neuromyelitis Optica Spectrum Disorder, AQP4-IgG positive): bilateral/simultaneous optic neuritis (severe, often does not recover well), longitudinally extensive transverse myelitis (LETM, >3 vertebral segments), area postrema syndrome (intractable hiccups/vomiting), no OCBs in CSF (usually), MRI lesions in cervical/thoracic cord (hypersignal central cord), brainstem, and hypothalamus — NOT typical MS periventricular Dawson fingers. Target: AQP4 on astrocyte endfeet. Treatment: rituximab/mycophenolate (not interferon-beta which may worsen NMO!)."]','A','NMO: bilateral optic neuritis + LETM + no OCBs + AQP4-IgG+. Interferon WORSENS NMO.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','medium','flashcard','What is the pathological hallmark of active and inactive MS plaques?','["Active MS plaque: perivenous T-cell and macrophage infiltrate. Loss of myelin (Luxol fast blue stain-negative). RELATIVE PRESERVATION OF AXONS (early). Macrophages contain myelin debris (foamy/lipid-laden). Inflammatory cells include CD4+ T cells (Th1, Th17), CD8+ T cells (which kill oligodendrocytes), B cells, plasma cells. Inactive plaque (chronic): demyelinated scar, gliosis (reactive astrocytes), oligodendrocyte loss, axonal loss (contributes to progressive disability). Shadow plaques: remyelinated zones with thin myelin sheaths."]','A','Active plaque = T cells + macrophages + myelin loss + PRESERVED AXONS. Chronic = gliosis + axon loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','medium','flashcard','What are the first-line disease-modifying therapies (DMTs) for RRMS?','["First-line (moderate efficacy): interferon-beta 1a/1b (SC/IM), glatiramer acetate (SC), dimethyl fumarate (oral), teriflunomide (oral). High-efficacy DMTs (second-line/high activity disease): natalizumab (anti-VLA-4, anti-trafficking), alemtuzumab (anti-CD52), ocrelizumab (anti-CD20, also approved for PPMS), cladribine (oral). RISK: natalizumab — PML (JC virus reactivation in JC Ab+/high index). Alemtuzumab — autoimmune complications (thyroid disease, ITP). Treatment goal: no evidence of disease activity (NEDA-3/4)."]','A','Interferons/GA = first line. Natalizumab/ocrelizumab = high efficacy. Natalizumab PML risk in JC+ patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','medium','flashcard','What is Uhthoff phenomenon and why does it occur in MS?','["Uhthoff phenomenon: temporary worsening of MS symptoms with an increase in core body temperature (exercise, fever, hot bath). Cause: demyelinated axons are particularly sensitive to temperature — even a small rise (0.5 degrees C) in temperature further slows or blocks conduction in already compromised demyelinated axons (REVERSIBLE conduction block). The phenomenon was first described with visual symptoms (temporary visual blurring with exercise). It resolves when temperature normalises. It does NOT represent a true relapse."]','A','Uhthoff = heat makes MS symptoms worse. Demyelinated axons conduct poorly when hot. Cools down = better.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','hard','flashcard','Explain the T cell-mediated autoimmune mechanism in MS pathogenesis.','["1) Peripheral activation: autoreactive T cells (reactive to myelin antigens: MBP, PLP, MOG) are activated in lymph nodes, possibly by molecular mimicry with viral antigens (EBV has been most strongly implicated). 2) BBB trafficking: activated T cells upregulate VLA-4 (alpha4-integrin) which binds VCAM-1 on CNS endothelium → T cells cross into CNS. 3) CNS reactivation: T cells encounter myelin antigens presented by microglia/macrophages (MHC II) and are reactivated → Th1 (IFN-gamma) and Th17 (IL-17) cytokines drive macrophage activation. 4) Oligodendrocyte/myelin destruction: by cytotoxic T cells (CD8+, direct killing via perforin/granzyme) and activated macrophages (phagocytosis)."]','A','T cells cross BBB via VLA-4/VCAM-1 (target of natalizumab). Reactivated in CNS → myelin destruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','hard','flashcard','What is progressive multifocal leukoencephalopathy (PML) and how is it related to MS treatment?','["PML: caused by JC virus (John Cunningham virus, polyomavirus) reactivating in immunocompromised patients. JC virus infects and destroys OLIGODENDROCYTES → multifocal demyelination. Presents: subacute cognitive/visual/motor decline without fever. MRI: large, bilateral, confluent white matter lesions without mass effect or enhancement (unlike MS plaques). In MS: PML is a serious complication of NATALIZUMAB treatment (anti-VLA-4 blocks lymphocyte trafficking into CNS, allowing JC virus reactivation). Risk stratified by JC Ab titre index. If PML suspected: stop natalizumab, plasma exchange (PLEX) to remove drug and restore immune trafficking (IRIS risk)."]','A','PML = JC virus destroys oligodendrocytes in immunocompromised. Natalizumab increases PML risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Demyelinating Diseases','easy','flashcard','What is Lhermitte sign and in what condition is it characteristic?','["Lhermitte sign: a brief electric shock-like sensation radiating down the spine and into the limbs on neck FLEXION. Caused by mechanical sensitisation of demyelinated axons in the cervical posterior columns (fine touch/vibration). Classic in MS (cervical cord plaques) but also in: cervical spondylotic myelopathy, subacute combined degeneration (B12 deficiency), radiation myelopathy, cisplatin toxicity. It is NOT pathognomonic of MS."]','A','Lhermitte: flex neck = electric shock down spine. Posterior column demyelination. Suggestive of MS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','easy','flashcard','What are the neuropathological hallmarks of Alzheimer disease?','["(1) SENILE PLAQUES (neuritic plaques): extracellular deposits of amyloid-beta 42, with surrounding dystrophic neurites, activated microglia, and astrocytes. Diffuse plaques (Abeta without neuritic reaction) precede neuritic plaques. (2) NEUROFIBRILLARY TANGLES (NFTs): intracellular paired helical filaments of hyperphosphorylated tau protein. Found in neurons that died (ghost tangles). (3) Amyloid angiopathy (CAA in vessel walls). (4) Synapse and neuronal loss. (5) Granulovacuolar degeneration in CA1 neurons. Braak staging (I-VI) describes NFT progression."]','A','AD hallmarks: amyloid plaques (outside) + tau tangles (inside) + synapse loss. Braak staging = NFT spread.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','easy','flashcard','What is the Braak staging system in Alzheimer disease?','["Braak staging describes the progression of NFTs (tau pathology): I-II: entorhinal cortex (EC) and transentorhinal cortex. III-IV: limbic system (hippocampus, amygdala, basal forebrain). V-VI: isocortex (association areas then primary cortex). Symptoms correlate with Braak stage: Braak I-II = preclinical/mild memory; Braak III-IV = mild cognitive impairment (MCI); Braak V-VI = overt dementia. Note: amyloid (Thal phases) often precedes tau (Braak stages) by years, but NFT burden better correlates with cognitive decline."]','A','Braak: EC first (I-II), hippo next (III-IV), cortex last (V-VI). NFT spread = disease progression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','medium','flashcard','Describe the genetics of Alzheimer disease (familial vs. sporadic).','["Early-onset familial AD (<65 yrs): PSEN1 (chromosome 14, presenilin-1, most common, hundreds of mutations), PSEN2 (chromosome 1, presenilin-2), APP (chromosome 21, amyloid precursor protein — also why Down syndrome patients develop AD). All cause increased Abeta42 production/aggregation. Late-onset sporadic AD (>65 yrs): APOE4 (chromosome 19) is the major risk factor (3x risk heterozygous, 8-12x homozygous). APOE4 reduces Abeta clearance and increases Abeta aggregation. Many other risk genes (TREM2, CLU, CR1, ABCA7) with smaller effects."]','A','Early AD: PSEN1 > PSEN2 > APP (all Abeta42 up). Late AD: APOE4 risk factor (not causative alone).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','medium','flashcard','What is the clinical presentation of Parkinson disease and what distinguishes it from atypical parkinsonism?','["Idiopathic PD (TRAP + asymmetry + good levodopa response): Tremor (resting, pill-rolling, 4-6 Hz), Rigidity (lead-pipe, cogwheeling), Akinesia/Bradykinesia, Postural instability (late). Asymmetric onset. NON-MOTOR: hyposmia (early), constipation, RBD (prodromal), depression, autonomic dysfunction, dementia (late). Levodopa response >30% improvement on UPDRS. Atypical parkinsonism (MSA, PSP, CBD): symmetric, early falls/autonomic/eye movement/limb dystonia/alien hand, POOR levodopa response."]','A','PD = TRAP + asymmetry + levodopa response. Atypical = symmetric, early falls, poor levodopa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','medium','flashcard','What are the pathological features of Parkinson disease?','["PD pathology: (1) Loss of dopaminergic neurons in the SUBSTANTIA NIGRA PARS COMPACTA (SNpc) — depigmentation of the nigra grossly visible at autopsy. (2) LEWY BODIES: round, eosinophilic, cytoplasmic inclusions with a pale halo, composed of aggregated alpha-synuclein (ubiquitinated). (3) LEWY NEURITES: alpha-synuclein-filled dystrophic neurites. Braak staging of LB pathology: Stage 1 (dorsal motor nucleus of CN X, olfactory bulb), Stage 2 (raphe, locus coeruleus), Stage 3-4 (SNpc — PD symptoms), Stage 5-6 (limbic and neocortex — PD dementia)."]','A','PD: SNpc depigmentation + Lewy bodies (alpha-syn) + Braak progression. SNpc death = dopamine deficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','medium','flashcard','What is the difference between Parkinson disease dementia (PDD) and dementia with Lewy bodies (DLB)?','["PDD: dementia occurring >1 year after the motor onset of established PD (''''one-year rule''''). DLB: dementia occurring BEFORE or within 1 year of parkinsonism onset. Both have: Lewy body pathology in cortex and limbic system, fluctuating cognition, visual hallucinations, parkinsonism. DLB additional features: neuroleptic sensitivity (antipsychotics cause severe rigidity), REM sleep behaviour disorder. Both are alpha-synucleinopathies. ''''1-year rule'''' distinguishes PDD from DLB (arbitrary but clinically useful)."]','A','PDD: motor PD then dementia (>1yr gap). DLB: dementia first or simultaneous with motor signs. 1-year rule.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','medium','flashcard','What is the cholinergic hypothesis of Alzheimer disease and how does it guide treatment?','["Cholinergic hypothesis: AD is caused/worsened by loss of cholinergic neurons in the NUCLEUS BASALIS OF MEYNERT (NBM, Ch4 area), which project to the hippocampus and cortex. ACh is critical for memory encoding. Treatment: ACETYLCHOLINESTERASE INHIBITORS (AChEIs) — donepezil, rivastigmine, galantamine — inhibit AChE and increase ACh in the synaptic cleft. Modest but significant cognitive benefit. Also: memantine (NMDA antagonist, used in moderate-severe AD) — reduces excitotoxicity from excess glutamate. Note: cholinergic loss is a consequence, not the initiating cause, of AD."]','A','Loss of NBM cholinergic neurons = low ACh. AChEIs (donepezil) inhibit AChE → more ACh → modest cognitive benefit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','hard','flashcard','What is the amyloid cascade hypothesis of AD and the evidence for it?','["Hardy and Higgins (1992): Abeta42 accumulation is the initiating event → Abeta oligomers and plaques → tau hyperphosphorylation → synaptic dysfunction → neuroinflammation → neuronal death. Evidence FOR: (1) All early-onset familial AD mutations increase Abeta42 (APP, PSEN1, PSEN2). (2) Down syndrome (trisomy 21, extra APP copy) develop AD by 50s. (3) APOE4 impairs Abeta clearance. (4) Abeta immunotherapy (lecanemab, donanemab) reduces plaques and slows cognitive decline in early AD (recently approved). Evidence AGAINST: (1) Many trials targeting Abeta failed. (2) Tau burden better correlates with cognition than plaques."]','A','Abeta cascade: APP cleavage → Abeta42 → oligomers → tau → death. Lecanemab approved = validates hypothesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','hard','flashcard','How does alpha-synuclein spread between neurons in Parkinson disease (prion-like hypothesis)?','["Prion-like propagation of alpha-synuclein: misfolded alpha-synuclein can seed aggregation of normal alpha-synuclein in naive neurons. Mechanisms: (1) Exosome-mediated secretion and uptake. (2) Trans-synaptic release and endocytosis. (3) Direct cell-to-cell transfer. Evidence: (1) Braak staging shows Lewy body pathology starts in brainstem/olfactory bulb and propagates in a predictable pattern. (2) Post-mortem studies of PD patients who received foetal mesencephalic neuron transplants showed host-to-graft Lewy body transmission after 11-16 years. (3) Injected PFFs (preformed fibrils) in animal models cause propagating LB pathology."]','A','Alpha-syn propagates like a prion: brain stem first (Braak 1-2), spreads upward. Supported by graft transmission studies.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases I','easy','flashcard','What are the first symptoms typically seen in Parkinson disease before motor onset (prodromal PD)?','["Prodromal (pre-motor) PD symptoms: (1) Hyposmia/anosmia (loss of smell — in >90%, often 4-6 years before diagnosis). (2) REM sleep behaviour disorder (RBD, acting out dreams — strongest predictor, ~80% develop alpha-synucleinopathy). (3) Constipation (GI motility dysfunction, Auerbach plexus Lewy bodies). (4) Depression/anxiety. (5) Urinary dysfunction. These precede motor symptoms by years and reflect early Lewy body pathology in the olfactory bulb, dorsal motor nucleus of CN X (gut), and locus coeruleus (Braak stages 1-2)."]','A','Prodromal PD: hyposmia + RBD + constipation = Braak stages 1-2. RBD is the strongest predictor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','easy','flashcard','What is Huntington disease and what are its clinical features?','["Huntington disease (HD): autosomal dominant, CAG trinucleotide repeat expansion (>36 repeats) in the HTT gene (chromosome 4p), producing polyglutamine expansion in mutant huntingtin (mHtt). Onset: typically 35-45 yrs (juvenile onset if >60 repeats). Clinical triad: (1) Chorea (early, involuntary writhing movements), (2) Psychiatric disturbance (depression, irritability, psychosis, personality change — often precede motor symptoms), (3) Cognitive decline (subcortical dementia). Later: akinesia, rigidity, dystonia, dysphagia. Death 10-15 years after onset. No disease-modifying treatment."]','A','HD: CAG repeat on chromosome 4 = polyglutamine = mHtt = chorea + psychiatry + dementia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','easy','flashcard','What is ALS and what is its mean survival from symptom onset?','["ALS (amyotrophic lateral sclerosis, Lou Gehrig disease): degeneration of BOTH upper motor neurons (corticospinal tract, motor cortex) AND lower motor neurons (anterior horn cells, motor cranial nuclei). Progressive weakness, wasting, fasciculations, spasticity, hyperreflexia, and bulbar symptoms (dysarthria, dysphagia). Cognition typically preserved (but 15% develop FTD). Diagnosis: El Escorial criteria. Mean survival: 2-5 years from symptom onset (most die from respiratory failure). Treatment: riluzole (glutamate inhibitor, extends survival ~3 months), edaravone."]','A','ALS = UMN + LMN signs at same time = unique combination. Respiratory failure = death. 2-5 year survival.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','medium','flashcard','What are the major genetic causes of familial ALS?','["C9orf72 GGGGCC hexanucleotide repeat (most common familial and sporadic cause), SOD1 (Cu/Zn superoxide dismutase 1, chromosome 21 — first gene found, ~20% familial ALS, gain of toxic function), TDP-43 (TARDBP gene mutations — but TDP-43 inclusions are the pathological hallmark of most ALS regardless of cause), FUS (fused in sarcoma), UBQLN2, OPTN. C9orf72 ALS + FTD: both FTD and ALS can occur in the same family due to C9orf72 expansion, indicating these are overlapping disease spectrums."]','A','C9orf72 = most common familial ALS. SOD1 = first found. TDP-43 = inclusions in almost ALL ALS. FUS = young onset.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','medium','flashcard','What pathological changes are seen in the brain and spinal cord of ALS patients?','["Spinal cord: loss of large alpha motor neurons in anterior horns with reactive gliosis. Atrophy and pallor of the corticospinal tract (lateral funiculi). In the brain: loss of Betz cells (giant pyramidal neurons) in the motor cortex (primary motor cortex atrophy), degeneration of corticospinal fibres in the posterior limb of internal capsule and cerebral peduncles. TDP-43 inclusions: cytoplasmic ubiquitinated, phosphorylated TDP-43 inclusions in surviving motor neurons (in >95% of ALS, regardless of genetic cause). C9orf72 ALS also shows p62/TDP-43 inclusions in cerebellum and hippocampus."]','A','ALS: anterior horn cell loss + corticospinal tract pallor + TDP-43 cytoplasmic inclusions (pathognomonic).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','medium','flashcard','What are the clinical and pathological differences between sporadic CJD and variant CJD (vCJD)?','["Sporadic CJD: elderly (mean 65 yrs), rapid course (4-6 months), dementia + myoclonus + cerebellar/visual signs, PSWC on EEG, DWI cortical ribboning/basal ganglia hyperintensity, 14-3-3+ in CSF, RT-QuIC+. Histology: cortical spongiform change, neuronal loss, astrocytosis, PrPsc plaques. Variant CJD: young patients (<40 yrs), psychiatric onset, longer course (~14 months), NO PSWCs, florid amyloid plaques (PrPsc surrounded by spongiform vacuoles), tonsillar biopsy PrPsc positive (unique to vCJD), linked to BSE exposure."]','A','Sporadic CJD = old, fast, EEG changes. vCJD = young, psychiatric onset, florid plaques, tonsil biopsy positive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','medium','flashcard','What is the inheritance and clinical features of Huntington disease anticipation?','["HD anticipation: CAG repeat length INCREASES with each generation (due to instability during paternal meiosis), causing earlier onset and more severe disease in successive generations. Normal alleles: <26 repeats. Premutation: 27-35 repeats (not clinically affected, but unstable). Reduced penetrance: 36-39 repeats (some develop HD). Full penetrance: >=40 repeats (all develop HD by old age). Juvenile HD: >=60 repeats, often from paternal transmission, presents with akinetic-rigid syndrome rather than chorea."]','A','Anticipation: more CAG repeats = earlier onset. Father passes longer repeats. >60 = juvenile HD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','medium','flashcard','What is fatal familial insomnia (FFI)?','["FFI: autosomal dominant prion disease. Caused by D178N mutation in PRNP codon 178, combined with methionine (not valine) at codon 129 on the SAME allele. Progressive untreatable INSOMNIA (complete), autonomic hyperactivation (tachycardia, hyperthermia, hypertension, hyperhidrosis), motor problems (ataxia, myoclonus), then dementia. Pathology: severe selective degeneration of the THALAMUS (especially dorsomedial and anterior nuclei — sleep regulation centres) with minimal spongiform change. Death within 1-3 years. EEG: loss of sleep spindles and K-complexes."]','A','FFI: PRNP D178N + Met129. Intractable insomnia. Thalamus degenerates. Cannot sleep = die.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','hard','flashcard','What is the mechanism of neuronal toxicity of mutant huntingtin (mHtt) in HD?','["mHtt toxicity (multiple mechanisms): 1) Nuclear toxicity: mHtt aggregates in the nucleus, sequestrating CREB-binding protein (CBP) and transcription factor Sp1 → transcriptional dysregulation (particularly BDNF transcription). 2) Loss of cortical BDNF: mHtt impairs BDNF vesicle transport → reduced cortical BDNF delivery to striatum → striatal neuronal death. 3) Mitochondrial dysfunction: mHtt binds complex II/III of ETC → oxidative stress. 4) Excitotoxicity: striatal neurons are hypersensitive to glutamate (via NMDA receptors). 5) Impaired protein clearance: mHtt inhibits proteasomal and autophagic pathways."]','A','mHtt: nuclear aggregation (blocks CBP/CREB), BDNF transport failure, mitochondrial damage, excitotoxicity.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','hard','flashcard','What is the significance of TDP-43 pathology in ALS and FTD?','["TDP-43 (TAR DNA-binding protein 43, gene TARDBP): normal nuclear RNA-binding protein. In ALS and most FTD-TDP: TDP-43 mislocalises from nucleus to cytoplasm, forms ubiquitinated, phosphorylated insoluble inclusions, is depleted from the nucleus. This causes: (1) Loss of nuclear TDP-43 function: impaired RNA splicing (including UNC13A and STMN2 — key neuronal transcripts). (2) Gain of cytoplasmic toxic function (aggregates). TDP-43 inclusions found in >95% of ALS (regardless of genetic cause) and in ~50% of FTD (FTD-TDP). FUS inclusions are an alternative in ~5% of ALS."]','A','TDP-43 nuclear to cytoplasm = nuclear function lost + cytoplasmic toxicity. Pathognomonic of most ALS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Neurodegenerative Diseases II','easy','flashcard','What is the triad of sporadic Creutzfeldt-Jakob disease (CJD)?','["Sporadic CJD triad: (1) Rapidly progressive DEMENTIA (days to weeks). (2) MYOCLONUS (startle-sensitive, multifocal). (3) PERIODIC SHARP WAVE COMPLEXES (PSWCs) on EEG (triphasic, 1-2 Hz). Additional features: cerebellar ataxia, cortical blindness, extrapyramidal signs. CSF: elevated 14-3-3 protein, elevated tau. MRI DWI: cortical ribboning and/or basal ganglia (caudate, putamen) hyperintensity — CT-QuIC/RT-QuIC in CSF is now the most sensitive diagnostic test. Median survival: 4-6 months. Universal fatality."]','A','CJD triad: RAPID DEMENTIA + MYOCLONUS + PSWCs on EEG. 4-6 months to death.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','easy','flashcard','What are the WHO grade 4 histological features of glioblastoma (GBM)?','["GBM WHO grade 4 histological features: (1) PSEUDOPALISADING NECROSIS: tumour cells arranged in bands around central necrosis (ischaemic necrosis with pseudopalisading is DEFINING for WHO grade 4). (2) MICROVASCULAR PROLIFERATION: glomeruloid tufts of proliferating endothelial cells and pericytes (angiogenesis). Both features must be present for grade 4. Also: marked nuclear pleomorphism, high mitotic rate, giant cells. GBM is divided into IDH-wildtype (primary GBM, ~90%, adults, aggressive) and IDH-mutant grade 4 (formerly called secondary GBM, better prognosis)."]','A','GBM = pseudopalisading necrosis + microvascular proliferation. IDH-wildtype = primary (worst). Both needed for grade 4.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','easy','flashcard','What are the molecular subtypes of gliomas in the 2021 WHO CNS tumour classification?','["WHO 2021 molecular classification: (1) Glioblastoma IDH-wildtype (grade 4): EGFR amplification/mutation, TERT promoter mutation, +7/-10 chromosomal pattern, or CDKN2A/B homozygous deletion. (2) Astrocytoma IDH-mutant (grades 2-4): IDH mutation + ATRX loss + TP53 mutation. (3) Oligodendroglioma IDH-mutant, 1p/19q co-deleted (grades 2-3): IDH mutation + 1p/19q co-deletion + TERT promoter mutation. Molecular markers now supersede histology for classification (integrated diagnosis)."]','A','Glio grade 4: IDH-wt + EGFR/TERT. Astrocytoma: IDH-mut + ATRX loss. Oligo: IDH-mut + 1p/19q del.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','medium','flashcard','What is the standard treatment for glioblastoma (GBM) (Stupp protocol)?','["Stupp protocol (2005): (1) Maximal safe surgical RESECTION (tumour debulking). (2) Concurrent RADIOTHERAPY (60 Gy in 30 fractions over 6 weeks) + TEMOZOLOMIDE (TMZ, 75 mg/m2/day oral during RT). (3) ADJUVANT TMZ for 6 cycles (150-200 mg/m2 5/28 days). +/- BEVACIZUMAB (anti-VEGF, for recurrence). MGMT promoter methylation: best predictor of benefit from TMZ. Median OS: ~14.6 months with Stupp vs. ~12 months without. GBM almost universally recurs. Tumor treating fields (TTFields, Optune) added in some guidelines."]','A','Stupp = surgery + RT + TMZ concurrent then adjuvant. MGMT methylation = TMZ benefit. GBM recurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','medium','flashcard','What is the clinical significance of IDH mutation in gliomas?','["IDH1/IDH2 mutations: present in most lower-grade gliomas (astrocytoma grade 2/3, oligodendroglioma) and secondary GBM. SIGNIFICANCE: (1) Better prognosis compared to IDH-wildtype GBM (median OS of IDH-mutant grade 3: ~7-8 years vs. IDH-wildtype GBM: ~15 months). (2) Produce oncometabolite 2-hydroxyglutarate (2-HG) causing CpG island methylator phenotype (CIMP) — extensive DNA hypermethylation. (3) Detectable by immunohistochemistry (IDH1 R132H antibody) or sequencing. (4) CSF/blood liquid biopsy using ctDNA for IDH mutations is emerging."]','A','IDH mutant = better prognosis than IDH wildtype GBM. 2-HG oncometabolite → CIMP epigenetic changes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','medium','flashcard','What are the clinical features and management of meningioma?','["Meningioma: typically BENIGN (WHO grade 1, ~80%), extra-axial (outside brain), dura-attached. Origin: arachnoid cap cells. Most common locations: cerebral convexity, parasagittal, sphenoid wing, olfactory groove, posterior fossa (CPA). Presentation: depends on location — seizures (parasagittal), visual loss (sphenoid wing), anosmia (olfactory groove), myelopathy (spinal). Histology: meningothelial whorls, psammoma bodies (grade 1 subtype). Risk factors: prior radiation, NF2, female sex (progesterone receptors). Treatment: observation, radiosurgery, or surgery. Grade 2 (atypical) and grade 3 (anaplastic/malignant) have higher recurrence."]','A','Meningioma: arachnoid cap cells. Dura-attached. Whorls + psammoma bodies. Usually benign grade 1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','medium','flashcard','What is the MGMT gene and why does its methylation status matter in GBM?','["MGMT (O6-methylguanine-DNA methyltransferase): DNA repair enzyme that removes methyl and alkyl adducts from the O6 position of guanine. Temozolomide (TMZ) alkylates this position, creating DNA damage that triggers cell death. MGMT repairs this damage, causing resistance. MGMT PROMOTER METHYLATION silences MGMT expression → reduced DNA repair → increased TMZ efficacy. Testing: methylation-specific PCR or pyrosequencing of the MGMT promoter. ~50% of GBM are MGMT methylated. MGMT methylation: also a prognostic factor independent of chemotherapy. Used to guide TMZ treatment decisions, especially in elderly GBM patients."]','A','MGMT fixes TMZ damage. MGMT methylated = silenced MGMT = can''''t repair = TMZ works better.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','medium','flashcard','What are the immunohistochemical markers used in CNS tumour diagnosis?','["GFAP (glial fibrillary acidic protein): astrocytic tumours (GBM, astrocytoma), ependymoma, some glioneuronal tumours. S100: schwannomas, meningiomas, melanoma. EMA (epithelial membrane antigen): meningioma (membranous pattern), ependymoma (dot-like/ring). OLIG2: oligodendroglial lineage, useful in glioma diagnosis. NeuN/Synaptophysin/Chromogranin: neuronal differentiation (ganglioglioma, medulloblastoma). IDH1 R132H: IDH-mutant glioma vs. reactive gliosis. INI1/SMARCB1 loss: atypical teratoid/rhabdoid tumour (AT/RT). H3 K27M: midline glioma H3 K27-altered (worst prognosis)."]','A','GFAP = glial. EMA = meningioma/ependymoma. IDH1 R132H = IDH-mutant glioma. INI1 loss = AT/RT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','hard','flashcard','How does bevacizumab work in GBM and why does it not improve overall survival?','["Bevacizumab: anti-VEGF (vascular endothelial growth factor) monoclonal antibody that inhibits angiogenesis — GBM is highly angiogenic (microvascular proliferation). Effects in GBM: reduces gadolinium enhancement on MRI (normalises BBB → less leak), reduces vasogenic oedema (allows corticosteroid dose reduction), improves progression-free survival in recurrent GBM. However: does NOT improve overall survival. The MRI response is partly a pseudoresponse (reduction in enhancement, not true tumour regression). Bevacizumab shifts the tumour to an infiltrative, non-enhancing phenotype, which still grows and kills."]','A','Bevacizumab: anti-VEGF = less angiogenesis = less enhancement but no OS benefit. Pseudoresponse on MRI.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','hard','flashcard','What are the familial CNS tumour syndromes and their associated tumours?','["NF1 (17q11, NF1/neurofibromin): pilocytic astrocytoma (optic pathway glioma), MPNST, neurofibroma. NF2 (22q12, NF2/merlin): bilateral vestibular schwannomas, meningiomas, spinal ependymomas. VHL (3p25): haemangioblastoma (retina + cerebellum), clear cell RCC, phaeochromocytoma. TSC (TSC1/TSC2, mTOR): SEGA, cortical tubers, renal angiomyolipoma, pulmonary LAM. Li-Fraumeni (TP53): GBM, medulloblastoma (desmoplastic). Gorlin syndrome (PTCH1, SHH pathway): medulloblastoma (desmoplastic/nodular, basal cell carcinoma)."]','A','NF1 = optic glioma. NF2 = bilateral schwannoma. VHL = haemangioblastoma. TSC = SEGA. VHL on chromosome 3.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours I','easy','flashcard','What is the WHO grading system for gliomas and meningiomas?','["WHO 2021 grading (1-4): Grade 1: circumscribed, low risk, curable by surgery (pilocytic astrocytoma, meningioma grade 1, craniopharyngioma). Grade 2: diffuse, low mitotic rate, lower risk (astrocytoma IDH-mut grade 2, oligodendroglioma grade 2, meningioma grade 2 atypical). Grade 3: anaplastic, higher mitotic rate (astrocytoma grade 3, oligodendroglioma grade 3, meningioma grade 3). Grade 4: highly malignant (GBM, medulloblastoma, PNET). Grading is now integrated (histological + molecular)."]','A','Grade 1 = cured by surgery. Grade 4 = deadly. Integrated molecular-histological grading from 2021.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','easy','flashcard','What is medulloblastoma and what are its clinical features?','["Medulloblastoma (WHO grade 4): most common malignant brain tumour of CHILDHOOD (<15 yrs). Location: cerebellar vermis (children) → compresses 4th ventricle. Presentation: obstructive hydrocephalus (headache, vomiting, papilloedema), truncal ataxia, broad-based gait. Drop metastases via CSF to the spinal cord (''''sugar-coating'''' of spinal cord on contrast MRI). Treatment: surgical resection + craniospinal irradiation (>3 yrs) + chemotherapy (vincristine, cisplatin). 5-year survival: ~60-70% overall (much better for WNT-activated subgroup)."]','A','Medulloblastoma: child + cerebellar vermis + 4th ventricle hydrocephalus + CSF spread. Most common malignant paediatric brain tumour.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','easy','flashcard','What is a craniopharyngioma and why does it cause specific clinical features?','["Craniopharyngioma: benign (WHO grade 1) tumour of the sellar/suprasellar region arising from Rathke pouch remnants. Clinical features: (1) Bitemporal hemianopia (optic chiasm compression). (2) Hypopituitarism (pituitary stalk compression): GH deficiency (commonest), gonadotrophin deficiency, hypothyroidism, hypocortisolism. (3) Diabetes insipidus (posterior pituitary/hypothalamus involvement). (4) Hydrocephalus (3rd ventricle obstruction). (5) Hypothalamic obesity (damage to satiety centres). Adamantinomatous type (children): cystic, calcified, machine-oil fluid, cholesterol crystals."]','A','Craniopharyngioma: optic chiasm = bitemporal hemianopia. Pituitary stalk = panhypopituitarism. Rathke pouch.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','medium','flashcard','What are the four molecular subgroups of medulloblastoma and their prognoses?','["WNT-activated (~10%): best prognosis (>95% 5-yr OS), nuclear beta-catenin, classic histology, usually NOT metastatic. SHH-activated (~30%): intermediate prognosis (70-80%), desmoplastic/nodular histology (good prognosis) or large cell/anaplastic (poor); PTCH1 mutations; infant and adult peaks. Group 3 (~25%): worst prognosis (~50% 5-yr OS), MYC amplification, classic/large-cell-anaplastic histology, high metastatic rate. Group 4 (~35%): intermediate, most common, MYCN/CDK6 amplification, classic histology. Age: WNT = children/adolescents; SHH = infants + adults; Groups 3/4 = children."]','A','Medulloblastoma prognosis: WNT=best (95%). SHH=good/bad depending. Group 3=worst. Group 4=intermediate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','medium','flashcard','What are the typical features of ependymoma by anatomical location?','["Posterior fossa (4th ventricle, children): presents with hydrocephalus/truncal ataxia. Grows through foramina of Luschka/Magendie. Spinal (intradural extramedullary, adults): most common is myxopapillary ependymoma at conus/filum terminale — lobulated, papillary with mucoid stroma, WHO grade 2. Supratentorial (cerebral hemispheres, adults/adolescents): often in white matter, associated with ZFTA-RELA fusion (most common supratentorial ependymoma). IHC: GFAP+, EMA dot-like positivity, L1CAM (ZFTA-RELA), HOXB13 (spinal ependymomas). Treatment: gross total resection."]','A','Ependymoma: children = posterior fossa/4th ventricle. Adults = spinal myxopapillary (conus/filum). Supratentorial = RELA fusion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','medium','flashcard','What is a pilocytic astrocytoma and how does it differ from diffuse astrocytoma?','["Pilocytic astrocytoma (PA, WHO grade 1): CIRCUMSCRIBED (not diffuse/infiltrating), associated with BRAF-KIAA1549 fusion (most common, ~70%). Occurs in children/young adults, posterior fossa/cerebellum, optic pathway, hypothalamus. MRI: cystic lesion with enhancing mural nodule. Histology: biphasic (compact pilocytic and loose multipolar areas), Rosenthal fibres, eosinophilic granular bodies. EXCELLENT prognosis: >90% 5-year survival after surgery. Diffuse astrocytoma (IDH-mutant, grade 2): infiltrating (blends with normal brain), no sharp margins, may not enhance, recurs and progresses to higher grade, IDH-mutant."]','A','Pilocytic = circumscribed, BRAF fusion, grade 1, curable by surgery. Diffuse = infiltrating, IDH-mutant, recurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','medium','flashcard','What is primary CNS lymphoma (PCNSL) and how is it managed?','["PCNSL: diffuse large B-cell lymphoma (DLBCL) confined to the CNS (brain, vitreous, spinal cord, CSF). No systemic lymphoma. Epidemiology: immunocompetent (increasing incidence in elderly) and immunocompromised (HIV, transplant — EBV-driven). MRI: homogeneous contrast-enhancing periventricular mass(es). KEY: AVOID STEROIDS before biopsy (they cause lymphoma cells to disappear temporarily = steroid effect, making diagnosis impossible). Treatment: high-dose methotrexate (MTX)-based chemotherapy (HD-MTX crosses BBB) +/- rituximab, then whole-brain radiotherapy (deferred in elderly due to neurotoxicity) or consolidation with ASCT."]','A','PCNSL: periventricular enhancing mass. DO NOT GIVE STEROIDS before biopsy. MTX is the backbone of treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','medium','flashcard','What is a vestibular schwannoma (acoustic neuroma) and how does it present?','["Vestibular schwannoma: benign (WHO grade 1) Schwann cell tumour arising from the vestibular division of CN VIII at the internal auditory canal/CPA. Most common CPA tumour. Pathology: Antoni A tissue (compact cells with Verocay bodies — nuclear palisading) and Antoni B tissue (loose, myxoid). IHC: S100+, SOX10+. Clinical: unilateral sensorineural hearing loss (SNHL, most common and earliest), tinnitus, disequilibrium. Large tumours: facial nerve (CN VII) palsy, CN V numbness, and brainstem compression. Treatment: observation, stereotactic radiosurgery (Gamma Knife), or microsurgical resection."]','A','Acoustic neuroma: CN VIII, CPA, unilateral SNHL. Antoni A + B pattern. S100+. NF2 = BILATERAL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','hard','flashcard','What is the significance of the BRAF V600E mutation in paediatric brain tumours?','["BRAF V600E mutation: found in ~15-20% of pilocytic astrocytomas (less common than BRAF fusion), 50-60% of pleomorphic xanthoastrocytoma (PXA), 25-30% of ganglioglioma, and many papillary craniopharyngioma. Clinical significance: (1) Diagnostic: BRAF V600E IHC (VE1 antibody) helps classify difficult cases. (2) Therapeutic: BRAF V600E inhibitors (vemurafenib, dabrafenib) +/- MEK inhibitors (trametinib, cobimetinib) are effective in BRAF V600E-positive brain tumours — now approved options for recurrent/progressive disease. (3) Contrast with BRAF-KIAA1549 fusion (pilocytic astrocytoma) which activates BRAF constitutively but is NOT targetable by V600E inhibitors."]','A','BRAF V600E = PXA, ganglioglioma, some pilocytic. Targetable with vemurafenib/dabrafenib. Different from BRAF fusion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','hard','flashcard','What is the difference between a primary and secondary CNS lymphoma?','["Primary CNS lymphoma (PCNSL): lymphoma confined to the CNS (brain, spinal cord, eyes, CSF) at diagnosis with no evidence of systemic lymphoma. Almost always DLBCL. Non-germinal centre B-cell (non-GCB/ABC) subtype. MYD88 L265P mutation in ~80% and CD79B mutation common. Secondary CNS lymphoma: systemic lymphoma that has spread to the CNS (leptomeningeal or parenchymal). Can be any histological subtype matching the primary systemic lymphoma. Has different prognosis and management (CNS prophylaxis for high-risk systemic lymphomas)."]','A','PCNSL = CNS only at diagnosis. Secondary = systemic lymphoma spreading to CNS. Both usually DLBCL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','CNS Tumours II','easy','flashcard','What is the clinical presentation and diagnosis of raised ICP from a brain tumour?','["Symptoms of raised ICP: HEADACHE (worse in the morning, worsened by bending/coughing/Valsalva), nausea/vomiting, papilloedema (bilateral optic disc swelling on fundoscopy), visual obscurations (transient greyouts). Cognitive/personality change, seizures, and focal deficits depend on location. Investigations: CT/MRI (contrast) to identify tumour and associated oedema/hydrocephalus. Treatment: DEXAMETHASONE (reduces vasogenic peritumoral oedema), mannitol for acute decompensation, surgery, radiotherapy, or steroids depending on tumour type."]','A','Brain tumour ICP: morning headache + papilloedema + nausea. Dexamethasone reduces peritumoral oedema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','easy','flashcard','What is Guillain-Barre syndrome (GBS) and what are its key clinical and CSF features?','["GBS (acute inflammatory demyelinating polyneuropathy, AIDP): acute immune-mediated demyelinating polyneuropathy. Ascending symmetrical weakness (legs first, then arms, then cranial nerves), AREFLEXIA, autonomic dysfunction (cardiac arrhythmia, BP lability), respiratory failure in 25-30%. CSF: ALBUMINOCYTOLOGIC DISSOCIATION (HIGH protein >0.45 g/L, NORMAL or near-normal WBC). This combination is pathognomonic. NCS: demyelinating pattern (slowed conduction velocity, conduction block, prolonged F-waves). Treatment: IVIG (0.4 g/kg/day for 5 days) OR plasma exchange (PLEX). Both equally effective. Steroids NOT beneficial."]','A','GBS: ascending weakness + areflexia + high CSF protein + normal WBC = albuminocytologic dissociation. IVIG or PLEX.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','easy','flashcard','What are the variants of GBS beyond the classic AIDP form?','["GBS variants: (1) AMAN (acute motor axonal neuropathy): pure motor, axonal, anti-GM1/GD1a antibodies, C. jejuni association, NCS: normal CV + reduced CMAP; common in China. (2) AMSAN (acute motor and sensory axonal neuropathy): motor + sensory axonal, severe, poor prognosis. (3) Miller Fisher syndrome (MFS): OPHTHALMOPLEGIA + ATAXIA + AREFLEXIA triad, anti-GQ1b antibodies (pathognomonic), no limb weakness usually. (4) Bickerstaff brainstem encephalitis: anti-GQ1b + altered consciousness/encephalopathy — MFS overlap. (5) Pharyngeal-cervical-brachial variant: bulbar and upper limb predominant."]','A','GBS variants: AMAN (motor axonal), MFS (ophthalmoplegia + ataxia + areflexia, anti-GQ1b). MFS eye, AMAN motor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','medium','flashcard','What is the pathological basis of Guillain-Barre syndrome (AIDP)?','["AIDP pathology: SEGMENTAL DEMYELINATION of peripheral nerves (Schwann cell damage) with perivenular and endoneurial lymphocytic infiltrates (CD4+ and CD8+ T cells, macrophages). Macrophages strip myelin from axons (myelinophagy). Nerve roots and proximal segments are preferentially affected. In recovery: remyelination occurs (Schwann cell proliferation) resulting in thin myelin sheaths and closely spaced nodes of Ranvier — explaining the prolonged recovery. Axons are typically preserved in classic AIDP (unlike axonal variants)."]','A','AIDP: T cells + macrophages strip myelin from Schwann cells. Segmental demyelination. Axons preserved.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','medium','flashcard','What is Charcot-Marie-Tooth disease (CMT) type 1A and how is it diagnosed?','["CMT1A: most common inherited neuropathy, autosomal dominant, caused by DUPLICATION of chromosome 17p11.2 containing the PMP22 gene (peripheral myelin protein 22). Clinical: progressive distal leg weakness and wasting (foot drop, pes cavus, hammer toes), glove-stocking sensory loss, absent reflexes, enlarged (hypertrophic) peripheral nerves. Onset: childhood/adolescence. Nerve biopsy: ONION BULB formation (concentric Schwann cell layers from repeated demyelination/remyelination). NCS: UNIFORMLY slow conduction velocities (<38 m/s in upper limbs). Diagnosis: genetic testing (MLPA for PMP22 duplication)."]','A','CMT1A: PMP22 duplication on chr 17p. Slow uniform NCV, onion bulbs, pes cavus. MLPA testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','medium','flashcard','What are the mechanisms and types of diabetic neuropathy?','["Types: (1) Distal symmetrical polyneuropathy (DSPN, most common): length-dependent sensorimotor, glove-stocking, starts with small fibre loss (pain/temperature), later large fibres. (2) Diabetic autonomic neuropathy: orthostatic hypotension, gastroparesis, erectile dysfunction, neurogenic bladder, anhidrosis. (3) Diabetic amyotrophy (proximal motor neuropathy, Bruns-Garland syndrome): severe acute proximal leg pain + wasting (asymmetric), from lumbosacral plexopathy/radiculopathy. (4) Mononeuropathy/mononeuritis multiplex: CN III palsy (pupil-sparing, due to ischaemia of the core), carpal tunnel, ulnar neuropathy. Mechanisms: polyol pathway, AGEs, oxidative stress, endoneurial microangiopathy."]','A','Diabetic neuropathy: DSPN (most common, glove-stocking), autonomic, amyotrophy, mononeuropathy. Microangiopathy + metabolic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','medium','flashcard','What is vasculitic neuropathy and how does it present?','["Vasculitic neuropathy: inflammation and necrosis of blood vessels in the epineurium/perineurium supplying peripheral nerves → axonal ischaemia/infarction → neuropathy. Pattern: MONONEURITIS MULTIPLEX (sequential involvement of individual named nerves, e.g., footdrop from peroneal nerve then wrist drop from radial nerve). May be in primary systemic vasculitis (polyarteritis nodosa, Churg-Strauss/EGPA, granulomatosis with polyangiitis) or non-systemic vasculitic neuropathy. Nerve biopsy: epineural vessel inflammation with wall necrosis and thrombosis, axonal degeneration/infarction."]','A','Vasculitic neuropathy = mononeuritis multiplex = infarction of individual nerve trunks. Vessel wall inflammation + necrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','medium','flashcard','What is hereditary neuropathy with liability to pressure palsies (HNPP)?','["HNPP: autosomal dominant, caused by DELETION of one copy of the PMP22 gene on chromosome 17p11.2 (opposite of CMT1A duplication). Clinical: recurrent focal pressure palsies at typical entrapment sites (peroneal nerve at fibula head causing footdrop, ulnar nerve at elbow, radial nerve) after minor compression/trauma. Usually recovers fully. NCS: focal slowing/conduction block at compression sites + diffuse mild slowing elsewhere. Nerve biopsy: focal thickening and folding of myelin (tomaculous neuropathy — tomacula = sausage-like myelin swellings)."]','A','HNPP = PMP22 DELETION (= CMT1A has duplication). Sausage myelin (tomacula). Recovers from pressure palsies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','hard','flashcard','What are the EMG/nerve conduction study (NCS) findings that distinguish demyelinating from axonal neuropathy?','["Demyelinating neuropathy: (1) Slow conduction velocity (CV <75% of lower limit of normal). (2) Prolonged or absent F-waves and H-reflexes. (3) Prolonged distal latencies. (4) Conduction block (CMAP decrement >50% from distal to proximal stimulation) — acquired demyelination. (5) Temporal dispersion (CMAP duration increase >30%). Axonal neuropathy: (1) Normal or near-normal CV. (2) Reduced CMAP amplitude (motor axon loss) or SNAP amplitude (sensory axon loss). (3) Normal or mildly prolonged latencies. (4) Fibrillations and positive sharp waves on EMG (denervation)."]','A','Demyelinating: slow CV, conduction block, prolonged latencies. Axonal: reduced amplitude, normal CV, fibrillations on EMG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','hard','flashcard','What is the pathophysiology of the albuminocytologic dissociation in GBS?','["In GBS, the inflammatory attack primarily targets the NERVE ROOTS (spinal nerve roots in the cauda equina and proximal peripheral nerves). The blood-nerve barrier (BNB) is DISRUPTED in the nerve roots, allowing PROTEIN to leak from serum into the CSF (the protein gradient is from blood to CSF). However, the blood-CSF barrier (choroid plexus) is relatively INTACT, so INFLAMMATORY CELLS (lymphocytes) are NOT as readily transferred into the CSF. The nerve root inflammation produces protein-rich exudate detectable in the CSF. Protein peaks at 4-6 weeks (when inflammation is maximal) and may remain elevated for months."]','A','GBS: nerve root BNB disrupted → protein leaks into CSF. Blood-CSF barrier intact → few white cells. = dissociation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Peripheral Neuropathies','easy','flashcard','What is the clinical significance of monitoring forced vital capacity (FVC) in GBS?','["In GBS, respiratory failure from diaphragm/intercostal weakness is the most feared complication. FVC monitoring guides ICU admission and intubation decisions. Rule of 20-30-40: Consider intubation if FVC <20 mL/kg, maximal inspiratory pressure (MIP) <30 cmH2O, or maximal expiratory pressure (MEP) <40 cmH2O. Serial FVC measurements every 4-6 hours in acute GBS. Rapid decline in FVC (>30% reduction) is an indication for elective intubation to avoid emergency intubation. Nadir of respiratory function occurs at 2-4 weeks (plateau phase)."]','A','FVC <20 mL/kg or >30% decline = intubate. 20-30-40 rule. Monitor frequently in acute GBS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','easy','flashcard','What is hippocampal sclerosis (HS) and how does it appear on MRI?','["HS: the most common pathological finding in drug-resistant MTLE. Macroscopic: firm, atrophied hippocampus. Histological: selective neuronal loss (CA1 predominantly > CA4 > CA3; relative sparing of CA2) with reactive gliosis in the hippocampus. Additional features: granule cell dispersion (widening of the dentate gyrus granule cell layer). MRI (T2/FLAIR coronal high-resolution sequences): (1) Hippocampal ATROPHY (volume loss, especially in CA1), (2) T2/FLAIR HYPERINTENSITY (gliosis = water content increase), (3) Loss of internal hippocampal architecture, (4) Ipsilateral fornix and mammillary body atrophy (secondary Wallerian degeneration)."]','A','HS: hippocampal atrophy + T2/FLAIR signal on MRI. CA1 most affected. Gliosis replaces lost neurons.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','easy','flashcard','What is focal cortical dysplasia (FCD) and what are the ILAE types?','["FCD: cortical malformations due to abnormal neuronal proliferation, migration, or organisation during embryological development, causing epilepsy. ILAE classification: FCD type I: subtle laminar disorganisation only (no dysmorphic cells), often associated with adjacent lesion (FCD IIIa-d). FCD type IIa: dysmorphic neurons (large, misoriented, cytoplasmic neurofilament) WITHOUT balloon cells. FCD type IIb (Taylor type): dysmorphic neurons + BALLOON CELLS (large cells with both neuronal and glial markers). FCD type III: FCD adjacent to a principal lesion (IIIa + HS, IIIb + tumour, IIIc + vascular malformation, IIId + acquired)."]','A','FCD: type IIb = dysmorphic neurons + balloon cells (pathognomonic). mTOR pathway. Drug-resistant epilepsy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','medium','flashcard','What is the mesial temporal lobe epilepsy (MTLE) syndrome and how is it treated?','["MTLE: most common drug-resistant focal epilepsy syndrome. Typically begins in childhood after a precipitating event (prolonged febrile seizure, encephalitis, trauma), then a latent period of years, then active MTLE. Seizure semiology: aura (rising epigastric, fear, deja vu, olfactory hallucination), then impaired awareness, automatisms (lip smacking, hand fumbling), post-ictal confusion. EEG: temporal lobe spikes, rhythmic theta at seizure onset. MRI: hippocampal sclerosis. Treatment: ASMs (carbamazepine, lamotrigine) — 30-40% become seizure-free. Surgery (temporal lobectomy, selective amygdalohippocampectomy): 60-70% seizure-free. LITT, RNS, VNS as alternatives."]','A','MTLE: aura + automatisms + post-ictal confusion. HS on MRI. 60-70% seizure-free after surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','medium','flashcard','What are the molecular mechanisms of focal cortical dysplasia type II?','["FCD type II: caused by somatic (post-zygotic) gain-of-function mutations in mTOR pathway genes: MTOR (most common, ~20-30% of FCD II), PIK3CA, PIK3R2, DEPDC5 (TSC1/2 negative regulator), AKT3. These mutations activate mTORC1 → increased protein synthesis, cell growth, abnormal migration/differentiation of cortical neurons. Because somatic: only a small subset of cortical cells are affected (mosaic mutation). Standard blood/saliva DNA testing often NEGATIVE — needs high-sensitivity NEXT-GENERATION SEQUENCING of brain tissue DNA. mTOR inhibitors (rapamycin/everolimus) reduce seizures in some FCD/TSC patients."]','A','FCD II = somatic mTOR pathway mutation. Blood DNA testing often negative. Need brain tissue for diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','medium','flashcard','What seizure types and EEG patterns are associated with mesial TLE?','["Mesial TLE seizure types: (1) Focal aware seizures (simple partial): aura without loss of awareness — epigastric rising sensation (most common), fear/anxiety, deja vu, jamais vu, olfactory hallucination (uncus). (2) Focal impaired awareness seizures (complex partial): impaired awareness + automatisms (oro-alimentary: lip smacking/chewing, manual: hand fumbling/picking), post-ictal confusion (minutes to hours) and dysphasia. (3) Focal to bilateral tonic-clonic seizures. Interictal EEG: anterior temporal spike-wave (TA1-TA2 electrodes). Ictal EEG: rhythmic 5-7 Hz theta from temporal lobe at seizure onset."]','A','MTLE aura = epigastric/fear/deja vu. Then impaired awareness + automatisms. Post-ictal confusion. Temporal theta on ictal EEG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','medium','flashcard','What is tuberous sclerosis complex (TSC) and what neurological features does it cause?','["TSC (hamartin TSC1 chromosome 9 or tuberin TSC2 chromosome 16 mutations): autosomal dominant neurocutaneous syndrome. Neurological features: (1) EPILEPSY (~80-90%, often infantile spasms → West syndrome → refractory focal epilepsy). (2) Intellectual disability (20-40%). (3) Autism spectrum disorder (~50%). (4) Subependymal nodules (periventricular calcified hamartomas). (5) Cortical/subcortical tubers (epileptogenic). (6) SEGA (subependymal giant cell astrocytoma) at foramen of Monro. Skin: ash-leaf macules (Wood lamp), angiofibromata, shagreen patches. Treatment: vigabatrin (infantile spasms in TSC), mTOR inhibitors (everolimus) for SEGA, tubers, lung LAM."]','A','TSC: epilepsy + tubers + SEGA + intellectual disability + skin signs. mTOR inhibitors (everolimus) effective.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','medium','flashcard','What is the surgical pathology of Rasmussen encephalitis?','["Rasmussen encephalitis (RE): rare, progressive inflammatory disease predominantly in children causing refractory focal epilepsy (epilepsia partialis continua = continuous motor seizure) and progressive unilateral hemispheric atrophy and hemiparesis. Pathology: perivascular lymphocytic infiltrates (predominantly CD8+ T cells), microglial nodules, astrogliosis, progressive cortical neuronal loss. Aetiology: likely immune-mediated (GluR3/AMPA receptor antibodies in some, but T-cell mediated in most). Treatment: functional hemispherectomy (disconnection) is the most effective for seizure control and halting progression."]','A','Rasmussen: CD8+ T cells destroy one hemisphere. Epilepsia partialis continua. Hemispherectomy = best treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','hard','flashcard','What are the proposed mechanisms of epileptogenesis in hippocampal sclerosis?','["Multiple mechanisms: (1) Loss of inhibitory interneurons (parvalbumin+ and somatostatin+ neurons most vulnerable) → reduced GABA-mediated inhibition → NET HYPEREXCITABILITY. (2) Mossy fibre sprouting: granule cell axons (mossy fibres) sprout into the inner molecular layer of the dentate gyrus (normally pruned in development), creating RECURRENT EXCITATORY circuits. (3) Astrocytic dysfunction: reactive astrocytes lose Kir4.1 potassium channels → impaired K+ buffering → extracellular K+ accumulation → neuronal depolarisation. (4) Altered receptor expression (GABA-A subunit changes reducing benzodiazepine sensitivity — explains pharmacoresistance). (5) Gap junction remodelling."]','A','HS epilepsy: interneuron loss → less GABA; mossy fibre sprouting → recurrent excitation; astrocyte K+ failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','hard','flashcard','How does the mTOR pathway contribute to cortical dysplasia and why are mTOR inhibitors being used in treatment?','["mTOR (mammalian target of rapamycin): serine/threonine kinase that integrates nutrient/growth factor signals to regulate protein synthesis, cell growth, and proliferation. In FCD and TSC: gain-of-function somatic mutations in MTOR, PIK3CA, AKT3 or loss-of-function in TSC1/TSC2 → hyperactivated mTORC1 → increased protein synthesis, abnormal cell size (cytomegaly), impaired differentiation and migration of cortical neurons during development. mTOR inhibitors (rapamycin/sirolimus, everolimus) competitively inhibit mTORC1 via FKBP12 complex → reduce giant cell/tuber size, reduce seizure frequency in TSC (EXIST-3 trial: 50% seizure reduction in ~40% of patients)."]','A','mTOR hyperactivation = big abnormal cells = FCD/TSC. Everolimus blocks mTOR → fewer seizures. EXIST-3 trial.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Epilepsy Pathology','easy','flashcard','What is drug-resistant epilepsy and what proportion of epilepsy patients are affected?','["Drug-resistant (pharmacoresistant) epilepsy: ILAE 2010 definition = failure of adequate trials of 2 or more appropriately chosen, adequately dosed anti-seizure medications (as monotherapy or combination). Affects ~30% of all people with epilepsy. After 2 failed ASMs, the probability of achieving seizure freedom with further drugs is <5%. Consequences: increased SUDEP risk (sudden unexpected death in epilepsy), cognitive decline, injury, depression, reduced quality of life. These patients should be referred to specialist epilepsy centres for surgical evaluation (10-year delay to surgery is common but harmful)."]','A','30% of epilepsy = drug resistant after 2 ASMs. ILAE = 2 failed drugs = drug resistant. Refer for surgery evaluation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','easy','flashcard','What is the Monro-Kellie doctrine and what are the types of cerebral oedema?','["Monro-Kellie: skull = rigid box with constant total volume (brain 80%, blood 10%, CSF 10%). Types of cerebral oedema: (1) VASOGENIC: BBB disruption → protein-rich fluid in white matter extracellular space (tumour, abscess, trauma). Responds to dexamethasone. (2) CYTOTOXIC: intracellular swelling due to Na+/K+ ATPase failure (ischaemia, hypoxia). Does NOT respond to dexamethasone. (3) OSMOTIC: plasma hypoosmolality causing water influx (hyponatraemia, SIADH). (4) INTERSTITIAL (transependymal): hydrocephalus → periventricular CSF seepage."]','A','Rigid skull = any increase raises ICP. Vasogenic = protein in WM (steroids help). Cytotoxic = intracellular (steroids no help).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','easy','flashcard','What is normal ICP and when does it become clinically significant?','["Normal ICP in adults: 7-15 mmHg (70-180 mmH2O). Mildly elevated: 15-20 mmHg. Moderate: 20-40 mmHg (requires treatment). Severe: >40 mmHg (imminent herniation risk). Refractory raised ICP: ICP persistently >20-25 mmHg despite tier 1 treatments (positioning, analgesia, sedation, normothermia, CPP maintenance). ICP waves: Lundberg A waves (plateau waves, 50-100 mmHg for 5-20 min = severely impaired compliance, near herniation). B waves (20-50 mmHg, 0.5-2/min = early signs of impaired compliance)."]','A','Normal ICP 7-15 mmHg. >20 = treat. >40 = herniation imminent. Lundberg A waves = crisis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','medium','flashcard','Describe the different types of brain herniation and their immediate clinical consequences.','["(1) Subfalcine (cingulate): cingulate gyrus under falx → ACA compression → contralateral leg weakness. (2) Transtentorial (uncal): uncus through tentorial notch → CN III compression (ipsilateral fixed dilated pupil), PCA compression (occipital infarction), midbrain compression (Duret haemorrhages, coma). (3) Tonsillar: cerebellar tonsils through foramen magnum → medulla compression → apnoea, cardiovascular collapse, death. (4) Upward transtentorial: posterior fossa mass pushes cerebellum through tentorial notch upward → midbrain compression (dorsal compression syndrome: Parinaud syndrome, hydrocephalus)."]','A','Subfalcine = ACA (leg). Uncal = CN III (blown pupil) + PCA. Tonsillar = medulla = death. Upward = posterior fossa mass.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','medium','flashcard','What are the Cushing triad and its mechanism?','["Cushing triad: (1) HYPERTENSION (widened pulse pressure, systolic hypertension): brainstem ischaemia from severely raised ICP triggers massive sympathetic discharge → systemic vasoconstriction → raised MAP to maintain CPP. (2) BRADYCARDIA: baroreceptors detect extreme hypertension → parasympathetic (vagal) reflex response. (3) IRREGULAR/SLOW RESPIRATIONS: medullary respiratory centre ischaemia → Cheyne-Stokes then ataxic breathing. Mechanism: CPP = MAP - ICP. When ICP approaches MAP, the brain mounts a terminal sympathetic surge to maintain perfusion. PRE-TERMINAL sign. Act immediately."]','A','Cushing: ICP rises → brainstem ischaemia → sympathetic surge (HTN) → baroreceptor → vagal (bradycardia). PRE-TERMINAL!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','medium','flashcard','What are the medical management options for acute raised ICP?','["Tier 0 (all patients): head elevation 30 degrees, head midline (venous drainage), normothermia, normoglycaemia, normocapnia (PaCO2 35-40 mmHg), adequate analgesia and sedation. Tier 1 (ICP >20 mmHg): osmotherapy (MANNITOL 0.25-1 g/kg IV bolus, or hypertonic saline 3% NaCl continuous/bolus), CSF drainage (EVD), moderate hyperventilation (PaCO2 30-35 mmHg for acute reduction only — causes vasoconstriction). Tier 2: barbiturate coma (thiopentone), therapeutic hypothermia (33-35 degrees). Tier 3: decompressive craniectomy. Dexamethasone: effective ONLY for VASOGENIC oedema (tumour, abscess), NOT for traumatic/ischaemic oedema."]','A','ICP management tiers: 0=position/normocapnia, 1=mannitol/EVD/hyperventilation, 2=barbiturate coma, 3=craniectomy. Dex only for vasogenic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','medium','flashcard','What is normal pressure hydrocephalus (NPH) and how is it diagnosed?','["NPH (Hakim-Adams syndrome): communicating hydrocephalus with NORMAL ICP on LP (<20 cmH2O) despite enlarged ventricles. Hakim-Adams triad: (1) GAIT APRAXIA (magnetic gait: wide-based, short steps, foot-floor sticking — gait first and most prominent). (2) URINARY INCONTINENCE. (3) DEMENTIA (frontal-subcortical: bradyphrenia, executive dysfunction, not Alzheimer-type). Investigations: MRI (enlarged ventricles disproportionate to sulci, transependymal flow, Evans ratio >0.3), high-volume LP (50 mL, temporary gait improvement post-tap = good predictor of shunt response), extended LP drainage trial. Treatment: ventriculoperitoneal shunt (VPS) or lumboperitoneal shunt."]','A','NPH: Gait + Urge incontinence + Dementia. Normal LP pressure. VPS = treatment. Gait improves first.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','medium','flashcard','What are the classic signs that differentiate the level of brain herniation?','["Level indicators: (1) Bilateral decorticate posturing (arms flexed, legs extended): suggests lesion at the level of the diencephalon-mesencephalon junction (upper brainstem). (2) Bilateral decerebrate posturing (arms extended, internally rotated): suggests midbrain/upper pons level lesion. (3) Flaccidity: pontine/medullary level (all posturing lost). (4) Ipsilateral fixed dilated pupil (blown pupil): CN III compression at tentorial level = uncal herniation. (5) Bilateral fixed mid-position pupils: midbrain level. (6) Pinpoint pupils: pontine level (preserved sympathetics but parasympathetics at pons level intact). Cranial nerve signs help localise the level."]','A','Decorticate = diencephalon. Decerebrate = midbrain/pons. Pinpoint pupils = pons. Fixed dilated pupil = uncal CN III.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','hard','flashcard','What is decompressive craniectomy (DC) and when is it indicated in raised ICP?','["DC: surgical removal of a large bone flap (typically 12x15 cm for traumatic or malignant MCA infarction) to provide space for the swelling brain, reducing ICP. Indications: (1) Malignant MCA infarction (HAMLET, DECIMAL, DESTINY trials): SPACE-occupying MCA infarction in patients <60 yrs (mainly), surgery within 48 hrs improves survival (reduces mortality from ~80% to ~20%) — but survivors may have severe disability. (2) TBI with refractory ICP >25 mmHg (DECRA trial: DC reduces ICP but does not improve outcomes vs. medical; RESCUEicp trial: DC reduces mortality but increases severely disabled survivors). (3) Posterior fossa lesions (malignant cerebellar infarction/haemorrhage) — suboccipital craniectomy."]','A','DC: remove bone = more room for swollen brain. Malignant MCA = within 48 hrs, <60 yrs. Reduces mortality but may increase disabled survivors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','hard','flashcard','What is idiopathic intracranial hypertension (IIH) and what are its pathophysiology and treatment?','["IIH (pseudotumor cerebri): raised ICP (>25 cmH2O) WITHOUT a structural lesion on neuroimaging, with normal CSF composition. Demographics: OBESE WOMEN OF CHILDBEARING AGE. Symptoms: HEADACHE (daily, positional), PULSATILE TINNITUS, VISUAL OBSCURATIONS, papilloedema (bilateral, can cause permanent visual loss). Sixth nerve palsy (false localising sign). MRI signs: empty sella, flattening of posterior globes, distension of optic nerve sheaths, transverse venous sinus stenosis. Pathophysiology: uncertain — excess CSF production? Impaired CSF absorption? Increased venous sinus pressure? Treatment: weight loss (most effective), ACETAZOLAMIDE (carbonic anhydrase inhibitor = reduces CSF production), topiramate. Serial LP if visual deterioration. LP/venous sinus stenting/optic nerve sheath fenestration for visual loss."]','A','IIH: obese woman + headache + papilloedema + normal MRI (except empty sella). Acetazolamide + weight loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pathology','Raised ICP & Herniation','easy','flashcard','What is papilloedema and how is it distinguished from a swollen disc for other reasons?','["Papilloedema: BILATERAL optic disc swelling specifically caused by raised INTRACRANIAL PRESSURE transmitted along the optic nerve sheaths. Features: blurring of disc margins, obscuration of vessels at disc margin, disc hyperaemia, venous engorgement, haemorrhages and exudates (late). Initially ASYMPTOMATIC (no acute visual loss — distinguishes from optic neuritis). Late papilloedema: enlarged blind spot, visual field constriction, and ultimately optic atrophy + permanent visual loss. Distinguished from other disc swelling: unilateral disc oedema (optic neuritis, AION, CRVO); pseudo-papilloedema (disc drusen — no haemorrhages, no venous engorgement)."]','A','Papilloedema: BILATERAL disc swelling from raised ICP. Initially no visual loss. Late = optic atrophy. LP may be needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');